import math

S = 2051325

def is_perfect_square(n):
    if n < 0:
        return False
    # Use math.isqrt for efficiency if available (Python 3.8+), otherwise int(sqrt)
    if hasattr(math, 'isqrt'):
        sqrt_n = math.isqrt(n)
    else:
        sqrt_n = int(math.sqrt(n))
    return sqrt_n * sqrt_n == n

def is_perfect_cube(n):
    if n == 0:
        return True
    # A robust way to check for perfect cube using floating point approximations 
    # and integer verification.
    cbrt_n = round(n**(1/3))
    # Check neighbors just in case of floating point error, though for these numbers it should be fine.
    # We only need to check the rounded value since the numbers are large but not astronomical.
    return cbrt_n**3 == n

