    2: {"m1": (2*S - 1, "sq"), "m2": (4*S - 1, "cb")},
    3: {"m1": (3*S - 1, "sq"), "m2": (9*S - 1, "cb")},
    4: {"m1": (4*S - 1, "sq"), "m2": (16*S - 1, "cb")}
}

